n,
first,
last,
change:last-first,
changePercent:first===0?null:((last-first)/Math.abs(first))*100,
volatility,
annualisedVolatility:volatility!==null&&periods?volatility*Math.sqrt(periods):null,
growth,
maxDrawdown:worst,
